'use client';

import { useState, useEffect } from 'react';
import { Menu } from 'lucide-react';
import { useKDSStore } from '../store/kdsStore';
import { useFilterStore } from '../store/useFilterStore';
import { kdsToast, KDSToastContainer } from './toast/KDSToast';
import { onPrintError } from '../services/printService';
import { SoundController } from './sound/SoundController';
import { ConnectivityManager } from './connectivity/ConnectivityManager';

export const KDSHeader: React.FC = () => {
    const [currentTime, setCurrentTime] = useState(new Date());

    const activeCount = useKDSStore((state) => Object.keys(state.orders).length);
    const completedCount = useKDSStore((state) => state.fulfilledOrders.length);
    const setIsSidebarOpen = useFilterStore((state) => state.setIsSidebarOpen);

    useEffect(() => {
        onPrintError((msg) => kdsToast.printError(msg));
        const timer = setInterval(() => setCurrentTime(new Date()), 1000);
        return () => clearInterval(timer);
    }, []);

    const formatDate = (date: Date) => {
        return date.toLocaleDateString('en-US', {
            weekday: 'long',
            year: '2-digit',
            month: 'numeric',
            day: 'numeric'
        });
    };

    const formatTime = (date: Date) => {
        return date.toLocaleTimeString('en-US', {
            hour: '2-digit',
            minute: '2-digit',
            hour12: true
        });
    };

    return (
        <>
            <SoundController />
            <ConnectivityManager />
            <KDSToastContainer />
            <header className="h-[56px] bg-white border-b border-gray-200 flex items-center justify-between px-6 shrink-0 z-50">
                {/* LEFT: Sidebar Toggle */}
                <div className="flex items-center w-1/4">
                    <button
                        onClick={() => setIsSidebarOpen(true)}
                        className="p-2 -ml-2 hover:bg-gray-100 rounded-lg transition-colors text-gray-900"
                    >
                        <Menu size={24} />
                    </button>
                </div>

                {/* CENTER: Navigation Tabs */}
                <div className="flex items-center h-full gap-8">
                    <div className="flex items-center h-full border-b-2 border-black px-1 relative">
                        <span className="text-sm font-bold tracking-tight text-black flex items-center gap-1.5 cursor-pointer uppercase">
                            Active <span className="opacity-40">{activeCount}</span>
                        </span>
                    </div>
                    <div className="flex items-center h-full px-1 border-b-2 border-transparent hover:border-gray-300 transition-all cursor-pointer">
                        <span className="text-sm font-bold tracking-tight text-gray-400 flex items-center gap-1.5 uppercase">
                            Scheduled <span className="opacity-40">0</span>
                        </span>
                    </div>
                    <div className="flex items-center h-full px-1 border-b-2 border-transparent hover:border-gray-300 transition-all cursor-pointer">
                        <span className="text-sm font-bold tracking-tight text-gray-400 flex items-center gap-1.5 uppercase">
                            Completed <span className="opacity-40">{completedCount}</span>
                        </span>
                    </div>
                </div>

                {/* RIGHT: Clock */}
                <div className="flex items-center justify-end w-1/4">
                    <span className="text-sm font-bold text-gray-900">
                        {formatDate(currentTime)} | {formatTime(currentTime)}
                    </span>
                </div>
            </header>
        </>
    );
};
